for n in ['G2A-c','G3A','G3B']:
 r=data['results'][n]['390'];rows+=f'<tr><td>{n}</td><td>{r["card"]["cardPct"]:.2f}%</td><td>{r["deep"]["fullyVisible"]}</td><td>{r["deep"]["provenanceCount"]} / 9</td></tr>'
