script='''const pick=document.getElementById('pick'),view=document.getElementById('view'),openLink=document.getElementById('open');let narrow=innerWidth<800;
function size(){view.style.width=narrow?'390px':'1440px';view.style.height=narrow?'844px':'900px';document.getElementById('phone').setAttribute('aria-pressed',narrow);document.getElementById('desktop').setAttribute('aria-pressed',!narrow)}
function load(){__LOAD__}pick.addEventListener('change',load);document.getElementById('reset').onclick=load;document.getElementById('phone').onclick=()=>{narrow=true;size()};document.getElementById('desktop').onclick=()=>{narrow=false;size()};size();load();'''
local_links='<p><a href="REPORT.md">Supporting report</a> · <a href="evidence/verification.json">Raw measurements &amp; scenarios</a> · <a href="evidence/supplement.json">Seam checks</a> · <a href="source-manifest.json">Source hashes</a> · <a href="references/owner-yellow-magnet.png">Yellow reference</a> · <a href="references/owner-ringed-magnet.png">Ringed reference</a> · <a href="standalone-comparison.html">Portable standalone comparison</a></p>'
local_script='const docs='+json.dumps(docs)+';'+script.replace('__LOAD__',"view.removeAttribute('srcdoc');view.src=docs[pick.value];openLink.href=docs[pick.value];")
(R/'index.html').write_text(body.replace('__LOCAL_LINKS__',local_links).replace('__SCRIPT__',local_script),encoding='utf-8')
